    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, win = p.window || 4, winS = win * 3600;
      const evDay = i.events * 1e6 * growth, rows = i.dbRows * 1e6 * growth, chg = (rows * i.changed) / 100;
      const rawGB = (evDay * i.evKB) / 1e6, dwhTB = (rawGB * COLUMNAR * 365 * RF) / 1000, rawTB = (rawGB * RAW_DAYS * RF) / 1000;
      return { growth, win, k: growth, evDay, rows, chg, logs: evDay / 86400, incr: chg / winS, full: rows / winS, xform: (evDay + chg) / winS, rawGB, dwhTB, rawTB,
        dwhNodes: Math.max(3, Math.ceil(dwhTB / NODE_TB)), rawNodes: Math.max(3, Math.ceil(rawTB / NODE_TB)), q: i.queries / 60, fileOps: 200 * growth,
        filesYear: ((FILES_RAW + FILES_OUT) * growth * 365) / 1e6 };
    },

